import { Link, useLocation } from 'react-router-dom'
import { Menu, CircleUserRound  } from 'lucide-react'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import navItems from '@/data/navItems'
import { useAuth } from '@/Contexts/AuthContext'
import { useFrappeAuth, useFrappeGetDoc } from 'frappe-react-sdk';



const NavMenu = () => {
    const {currentUser, logout} = useFrappeAuth()
    const { data } = useFrappeGetDoc(
      "User",
      currentUser as string
    );
    const {pathname} = useLocation()
    const isHome = pathname === '/'
  return (
    <>
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <div
            className={`flex items-center gap-2 p-2 rounded-full ${isHome ? "bg-gray-700" : "bg-gray-200"} hover:cursor-pointer`}
          >
            <Menu />
            {currentUser ? (
              <Avatar>
                <AvatarImage src={data?.user_image} />
                <AvatarFallback className="bg-black">
                  {currentUser[0].toUpperCase()}
                </AvatarFallback>
              </Avatar>
            ) : (
              <CircleUserRound />
            )}
          </div>
        </DropdownMenuTrigger>
        <DropdownMenuContent className="w-56" align="start">
          <DropdownMenuLabel>My Account</DropdownMenuLabel>
          <DropdownMenuGroup>
            <DropdownMenuItem>Profile</DropdownMenuItem>
            <DropdownMenuItem>Settings</DropdownMenuItem>
          </DropdownMenuGroup>
          <DropdownMenuSeparator />
          <DropdownMenuGroup className="lg:hidden">
            {navItems.map((item) => (
              <Link to={item.path}>
                <DropdownMenuItem>{item.label}</DropdownMenuItem>
              </Link>
            ))}
          </DropdownMenuGroup>
          {!currentUser && (
            <DropdownMenuGroup>
              <Link to="/my-profile">
                <DropdownMenuItem>Login</DropdownMenuItem>
              </Link>
              <Link to="/register">
                <DropdownMenuItem>Register</DropdownMenuItem>
              </Link>
            </DropdownMenuGroup>
          )}
          {currentUser && (
            <DropdownMenuGroup>
              <a href="/app/home">
                <DropdownMenuItem>Switch to Desk</DropdownMenuItem>
              </a>
              <DropdownMenuItem onClick={logout}>Log out</DropdownMenuItem>
            </DropdownMenuGroup>
          )}
        </DropdownMenuContent>
      </DropdownMenu>
    </>
  );
}

export default NavMenu