import zxcvbn from "zxcvbn";

export type PasswordFeedback = {
  score: number;
  warning: string;
  suggestions: string[];
  isValid: boolean;
};

// Default minimum password score (same as Frappe default: 2 = “good”)
const MINIMUM_PASSWORD_SCORE = 2;

export function validatePassword(password: string): PasswordFeedback {
  if (!password) {
    return {
      score: 0,
      warning: "Password cannot be empty.",
      suggestions: ["Please enter a password."],
      isValid: false,
    };
  }

  // Run zxcvbn (truncate to 128 chars like Frappe does)
  const result = zxcvbn(password.slice(0, 128));

  return {
    score: result.score,
    warning: result.feedback.warning || "",
    suggestions: result.feedback.suggestions || [],
    isValid: result.score >= MINIMUM_PASSWORD_SCORE,
  };
}
