import logo from '@/assets/urugano realty logo 1.png'
import { NavLink, useLocation, Link } from 'react-router-dom'
import NavMenu from '../base/NavMenu'
import navItems from '@/data/navItems'
import Container from './Container'

const Header = () => {
    const {pathname} = useLocation()
    const isHome = pathname === '/'

  return (
    <div className={`${isHome && 'bg-black'} pb-6`}>
        <Container className={`flex justify-between items-center py-4 ${isHome && 'text-white'}`}>
            <Link to='/'><img src={logo} alt="" className='h-8'/></Link>
            <div className='hidden lg:flex gap-12'>
                {
                    navItems.map((item) => (
                        <NavLink to={item.path}>
                            {item.label}
                        </NavLink>
                    ))
                }
            </div>
            <div className='flex gap-12 items-center'>
                <NavMenu/>
            </div>
        </Container>
    </div>
  )
}

export default Header