import { createBrowserRouter, createRoutesFromElements, Route } from 'react-router-dom'
import ProtectedRoute from './ProtectedRoute'
import MainLayout from "@/components/layout/MainLayout"
import Home from "@/pages/Home"
import Login from "@/pages/Login"
import PropertyDetails from '@/pages/PropertyDetails';
import SignUp from '@/pages/SignUp';

const router = createBrowserRouter(
  createRoutesFromElements(
    <Route path="/" element={<MainLayout />} >
      <Route index element={<Home/>} />
      <Route path="properties/:id" element={<PropertyDetails/>} />
      <Route path="signup" element={<SignUp/>} />
      <Route path="my-profile" element={<Login/>} />
      <Route path="dashboard" element={<ProtectedRoute><h1 className='text-3xl text-green-600'>Dashboard</h1></ProtectedRoute>} />
      <Route path="test" element={<h1 className='text-3xl text-green-600'>Test</h1>} />
    </Route>
  )
);

export default router;