import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useState } from "react";
import { useForm } from "react-hook-form";
import { PasswordInput } from "@/components/base/PasswordInput";
import { useFrappeCreateDoc } from "frappe-react-sdk";
import { validatePassword } from "@/utils/passwordValidator";

function SignUpForm() {
  const { createDoc, loading, error, isCompleted } = useFrappeCreateDoc();
  const {
    register,
    handleSubmit,
    formState: { errors, isSubmitting },
    reset,
    getValues,
    trigger,
  } = useForm();

  const [passwordFeedback, setPasswordFeedback] = useState<{
    score: number;
    warning: string;
    suggestions: string[];
    isValid: boolean;
  } | null>(null);

  const onSubmit = async (data: any) => {
    try {
      // extra validation (client-side)
      if (!passwordFeedback?.isValid) {
        throw new Error("Password too weak. Please choose a stronger one.");
      }

      const doc = await createDoc("User", {
        first_name: data.fullname,
        email: data.identifier,
        new_password: data.password,
        // roles: [{ role: "System User" }], // 👈 Assign at least one role
        send_welcome_email: 0,
      });
      console.log("✅ User created:", doc);
      reset();
    } catch (err) {
      console.error("❌ Failed:", err);
    }
  };

  return (
    <form
      onSubmit={handleSubmit(onSubmit)}
      className="bg-[#D9D9D936] rounded-md w-sm py-6 px-4 flex flex-col gap-4"
    >
      <p className="text-2xl font-bold text-center">Create Account</p>

      {/* Email/Username */}
      <Label htmlFor="identifier">Username or Email</Label>
      <Input
        {...register("identifier", { required: "Username/Email is required" })}
        type="email"
        id="identifier"
        className="bg-[#D8D8D8]"
      />
      {errors.identifier?.message && (
        <p className="text-red-500 text-sm">
          {errors.identifier.message as string}
        </p>
      )}

      {/* Full Name */}
      <Label htmlFor="fullname">Full Name</Label>
      <Input
        {...register("fullname", { required: "Full name is required" })}
        type="text"
        id="fullname"
        className="bg-[#D8D8D8]"
      />
      {errors.fullname?.message && (
        <p className="text-red-500 text-sm">
          {errors.fullname.message as string}
        </p>
      )}

      {/* Password */}
      <Label htmlFor="password">Password</Label>
      <PasswordInput
        {...register("password", { required: "Password is required" })}
        id="password"
        className="bg-[#D8D8D8]"
        onChange={(e) => {
          const result = validatePassword(e.target.value);
          setPasswordFeedback(result);
        }}
      />
      {errors.password?.message && (
        <p className="text-red-500 text-sm">
          {errors.password.message as string}
        </p>
      )}
      {passwordFeedback && (
        <div className="text-sm mt-1">
          <p>
            Strength:{" "}
            <strong
              className={` ${
                [
                  "text-red-600",
                  "text-yellow-600",
                  "text-yellow-500",
                  "text-green-500",
                  "text-green-600",
                ][passwordFeedback.score]
              }`}
            >
              {
                ["Very Weak", "Weak", "Fair", "Good", "Strong"][
                  passwordFeedback.score
                ]
              }
            </strong>
          </p>
          {passwordFeedback.warning && (
            <p className="text-yellow-600">{passwordFeedback.warning}</p>
          )}
          {passwordFeedback.suggestions.length > 0 && (
            <ul className="list-disc ml-4 text-gray-600">
              {passwordFeedback.suggestions.map((s, i) => (
                <li key={i}>{s}</li>
              ))}
            </ul>
          )}
        </div>
      )}

      {/* Confirm Password */}
      <Label htmlFor="confirmPassword">Confirm Password</Label>
      <PasswordInput
        {...register("confirmPassword", {
          required: "Password confirmation is required",
          validate: (value) =>
            value === getValues("password") || "Passwords do not match",
        })}
        id="confirmPassword"
        className="bg-[#D8D8D8]"
        onBlur={() => trigger("confirmPassword")}
      />
      {errors.confirmPassword?.message && (
        <p className="text-red-500 text-sm">
          {errors.confirmPassword.message as string}
        </p>
      )}

      {/* Server Errors */}
      {error && (
        <p className="text-red-600 text-sm">
          {error.message || "Server error while creating user"}
        </p>
      )}
      {isCompleted && (
        <p className="text-green-600 text-sm">
          ✅ Account created successfully
        </p>
      )}

      <Button disabled={isSubmitting || loading} type="submit" className="mt-4">
        {loading ? "Creating..." : "Submit"}
      </Button>
    </form>
  );
}

export default SignUpForm;
