import { createContext, useContext, useState, useEffect } from "react";
import type { ReactNode } from "react";
import type { User, AuthContextType } from "@/types";
import { redirect } from "react-router-dom";
import { fi } from "date-fns/locale";

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User>(null);

  async function login(email: string, password: string) {
    const res = await fetch("/api/method/login", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      credentials: "include",
      body: JSON.stringify({ usr: email, pwd: password }),
    });

    if (!res.ok) throw new Error("Login failed");
    setUser({ email });
  }

async function signup(email: string, first_name: string, last_name: string, password: string) {
  const res = await fetch("/api/method/urugano.api.custom_signup", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      email,
      first_name,
      last_name,
      password,
    }),
  });

  const data = await res.json().catch(() => ({}));

  if (!res.ok) {
    console.error("Signup failed:", data);
    throw new Error(data.message || "Signup failed");
  }

  return data;
}


  function logout() {
    fetch("/api/method/logout", { credentials: "include" });
    setUser(null);
  }

  useEffect(() => {
    async function checkUser() {
      const res = await fetch("/api/method/frappe.auth.get_logged_user", {
        credentials: "include",
      });
      if (res.ok) {
        const data = await res.json();
        setUser({ email: data.message });
      }
    }
    checkUser();
  }, []);

  return (
    <AuthContext.Provider value={{ user, login, signup, logout }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth must be used inside AuthProvider");
  return ctx;
}
